window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3d8c01527a58e5b4"]={"versions": [{"id": "FIG-3d8c01527a58e5b4", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm der AUTOSAR-Methodik (Methodology Activity Diagram) zur Darstellung eines methodischen Arbeitsschritts im Rahmen der Steuergeräte-Konfiguration (ECU Integration und BSW/SWC-Konfiguration). Es zeigt die Aktivität „Configure Memmap Allocation“ eingebettet in den Kontext der Zuordnung von Speicherelementen (Memory Sections) zu Speicherbereichen und Adressierungsmodi auf ECU-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Aktivität:</strong></p>\n<ul class=\"fig-list\">\n<li><code>Configure Memmap Allocation</code> (zentraler Prozessschritt)</li>\n</ul>\n<p class=\"fig-p\"><strong>Rollen / Akteure (Stereotyp <code>«performs»</code>, Multiplizität jeweils <code>0..1</code>):</strong></p>\n<ul class=\"fig-list\">\n<li><code>Basic Software Module Developer</code></li>\n<li><code>Software Component Developer</code></li>\n<li><code>ECU Integrator</code></li>\n</ul>\n<p class=\"fig-p\"><strong>Eingangsartefakte (Stereotyp <code>«input»</code>):</strong></p>\n<ul class=\"fig-list\">\n<li><code>VFB Types</code>: Bereitstellung von <code>+SwAddrMethods</code> (Kardinalität <code>0..*</code>)</li>\n<li><code>Basic Software Module Implementation Description</code>: Bereitstellung von <code>+MemorySections</code> (Kardinalität <code>0..*</code>)</li>\n<li><code>Atomic Software Component Implementation</code>: Bereitstellung von <code>+MemorySections</code> (Kardinalität <code>0..*</code>)</li>\n<li>Artefakt am unteren Rand (BSW-Modul-/MemMap-Definition): Bereitstellung von <code>+MemMapAddressingModeSet</code> (Kardinalität <code>1..*</code>)</li>\n</ul>\n<p class=\"fig-p\"><strong>Ausgangsartefakt (Stereotyp <code>«output»</code>):</strong></p>\n<ul class=\"fig-list\">\n<li><code>ECU Configuration Values</code>: Enthält <code>+MemMapAllocation</code> (Kardinalität <code>1</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Mindestens einer der beteiligten Akteure (<code>Basic Software Module Developer</code>, <code>Software Component Developer</code> oder <code>ECU Integrator</code>) führt die Aktivität <code>Configure Memmap Allocation</code> aus.</li>\n<li>Als Eingangsdaten fließen Software-Adressierungsmethoden (<code>+SwAddrMethods</code>) aus <code>VFB Types</code>, Speicherschnittstellen/Abschnitte (<code>+MemorySections</code>) aus der BSW-Modul-Implementierungsbeschreibung sowie aus SWC-Implementierungsbeschreibungen ein, ergänzt um die verfügbaren Adressierungsmodi (<code>+MemMapAddressingModeSet</code>).</li>\n<li>Die Aktivität ordnet die Speichersektionen den konkreten Adressierungskonzepten und Speicherlayouts zu.</li>\n<li>Als Ergebnis entsteht die konkrete Konfiguration <code>+MemMapAllocation</code> innerhalb der <code>ECU Configuration Values</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die methodische Vorschrift für die Erzeugung der Speicherkartierungs-Konfiguration (MemMap Allocation) in AUTOSAR. Entwickler und Integratoren müssen sicherstellen, dass alle in BSW und SWC deklarierten Memory Sections mit passenden SwAddrMethods verknüpft und gegen die im BSW deklarierten MemMapAddressingModeSets abgebildet werden. Die Kardinalität <code>0..1</code> an den Akteuren verdeutlicht, dass die Durchführung je nach Projektzuschnitt durch BSW-Entwickler, SWC-Entwickler oder den ECU-Integrator erfolgen kann.</p>"}, {"id": "FIG-79d5d259dd6d77bc", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm der AUTOSAR-Methodik (Methodology Activity Diagram) zur Darstellung eines methodischen Arbeitsschritts im Rahmen der Steuergeräte-Konfiguration (ECU Integration und BSW/SWC-Konfiguration). Es zeigt die Aktivität „Configure Memmap Allocation“ eingebettet in den Kontext der Zuordnung von Speicherelementen (Memory Sections) zu Speicherbereichen und Adressierungsmodi auf ECU-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Aktivität:</strong></p>\n<ul class=\"fig-list\">\n<li><code>Configure Memmap Allocation</code> (zentraler Prozessschritt)</li>\n</ul>\n<p class=\"fig-p\"><strong>Rollen / Akteure (Stereotyp <code>«performs»</code>, Multiplizität jeweils <code>0..1</code>):</strong></p>\n<ul class=\"fig-list\">\n<li><code>Basic Software Module Developer</code></li>\n<li><code>Software Component Developer</code></li>\n<li><code>ECU Integrator</code></li>\n</ul>\n<p class=\"fig-p\"><strong>Eingangsartefakte (Stereotyp <code>«input»</code>):</strong></p>\n<ul class=\"fig-list\">\n<li><code>VFB Types</code>: Bereitstellung von <code>+SwAddrMethods</code> (Kardinalität <code>0..*</code>)</li>\n<li><code>Basic Software Module Implementation Description</code>: Bereitstellung von <code>+MemorySections</code> (Kardinalität <code>0..*</code>)</li>\n<li><code>Atomic Software Component Implementation</code>: Bereitstellung von <code>+MemorySections</code> (Kardinalität <code>0..*</code>)</li>\n<li>Artefakt am unteren Rand (BSW-Modul-/MemMap-Definition): Bereitstellung von <code>+MemMapAddressingModeSet</code> (Kardinalität <code>1..*</code>)</li>\n</ul>\n<p class=\"fig-p\"><strong>Ausgangsartefakt (Stereotyp <code>«output»</code>):</strong></p>\n<ul class=\"fig-list\">\n<li><code>ECU Configuration Values</code>: Enthält <code>+MemMapAllocation</code> (Kardinalität <code>1</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Mindestens einer der beteiligten Akteure (<code>Basic Software Module Developer</code>, <code>Software Component Developer</code> oder <code>ECU Integrator</code>) führt die Aktivität <code>Configure Memmap Allocation</code> aus.</li>\n<li>Als Eingangsdaten fließen Software-Adressierungsmethoden (<code>+SwAddrMethods</code>) aus <code>VFB Types</code>, Speicherschnittstellen/Abschnitte (<code>+MemorySections</code>) aus der BSW-Modul-Implementierungsbeschreibung sowie aus SWC-Implementierungsbeschreibungen ein, ergänzt um die verfügbaren Adressierungsmodi (<code>+MemMapAddressingModeSet</code>).</li>\n<li>Die Aktivität ordnet die Speichersektionen den konkreten Adressierungskonzepten und Speicherlayouts zu.</li>\n<li>Als Ergebnis entsteht die konkrete Konfiguration <code>+MemMapAllocation</code> innerhalb der <code>ECU Configuration Values</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die methodische Vorschrift für die Erzeugung der Speicherkartierungs-Konfiguration (MemMap Allocation) in AUTOSAR. Entwickler und Integratoren müssen sicherstellen, dass alle in BSW und SWC deklarierten Memory Sections mit passenden SwAddrMethods verknüpft und gegen die im BSW deklarierten MemMapAddressingModeSets abgebildet werden. Die Kardinalität <code>0..1</code> an den Akteuren verdeutlicht, dass die Durchführung je nach Projektzuschnitt durch BSW-Entwickler, SWC-Entwickler oder den ECU-Integrator erfolgen kann.</p>"}], "trans": [{"from": "FIG-3d8c01527a58e5b4", "to": "FIG-79d5d259dd6d77bc", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
